namespace F1Manager {
public static class CanvasInk {
    public static void Text(Graphics g,string text,Rectangle r,int size,Color color,bool bold=false,bool wrap=false){using(var f=new Font("Segoe UI",size,bold?FontStyle.Bold:FontStyle.Regular,GraphicsUnit.Pixel))using(var b=new SolidBrush(color))using(var format=new StringFormat{LineAlignment=StringAlignment.Center,Trimming=StringTrimming.EllipsisCharacter,FormatFlags=wrap?0:StringFormatFlags.NoWrap})g.DrawString(text??"",f,b,r,format);}
    public static void Box(Graphics g,Rectangle r,Color fill,int radius=12){using(var p=Theme.Round(r,radius))using(var b=new SolidBrush(fill))g.FillPath(b,p);}
}
public class CalendarAdvanceOverlay:GameOverlay {
    readonly Career state;readonly Action save;readonly List<RaceCanvasAction> actions=new List<RaceCanvasAction>();readonly Dictionary<string,double> hover=new Dictionary<string,double>();Point pointer=new Point(-1,-1);double lastDay,lastFrame,frameDelta=.016;bool running=true;float scale=1;int ox,oy;internal string[] DayEvents=new string[0];internal int AdvancedDays;
    protected override bool UsesSheet {get{return false;}}internal override bool NeedsBackdrop {get{return false;}}
    public event Action Closed;
    public CalendarAdvanceOverlay(Career s,bool animated,Action persist):base(animated){state=s;save=persist;DayEvents=CalendarFlow.Events(s,s.Day).ToArray();MouseDown+=(o,e)=>{if(e.Button!=MouseButtons.Left)return;var pt=new Point((int)((e.X-ox)/scale),(int)((e.Y-oy)/scale));var action=actions.LastOrDefault(a=>a.Bounds.Contains(pt));if(action!=null)action.Execute();};MouseLeave+=(o,e)=>pointer=new Point(-1,-1);MouseMove+=(o,e)=>{pointer=new Point((int)((e.X-ox)/scale),(int)((e.Y-oy)/scale));Cursor=actions.Any(a=>a.Bounds.Contains(pointer))?Cursors.Hand:Cursors.Default;};}
    internal bool Running {get{return running;}}
    internal Point ActionPoint(string key){Refresh();var a=actions.Last(x=>x.Key==key);return new Point(ox+(int)((a.Bounds.X+a.Bounds.Width/2)*scale),oy+(int)((a.Bounds.Y+a.Bounds.Height/2)*scale));}
    internal void ClickAt(Point p){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));}
    internal void Toggle(){running=!running;lastDay=Clock.Elapsed.TotalSeconds;}
    internal void StepDay(){CalendarFlow.AdvanceOne(state);AdvancedDays++;DayEvents=CalendarFlow.Events(state,state.Day).ToArray();save();if(DayEvents.Length>0||CalendarFlow.Ready(state))running=false;Invalidate();}
    protected override void Advance(){double now=Clock.Elapsed.TotalSeconds;frameDelta=lastFrame==0?.016:Math.Min(.05,now-lastFrame);lastFrame=now;if(Closing)return;if(CalendarFlow.Ready(state)){running=false;return;}if(running&&Clock.Elapsed.TotalSeconds-lastDay>=CalendarFlow.DaySeconds){lastDay=Clock.Elapsed.TotalSeconds;StepDay();}}
    void Button(Graphics g,string key,string text,Rectangle r,Action a,bool primary=false){double value;hover.TryGetValue(key,out value);value=FrameClock.Approach(value,r.Contains(pointer)?1:0,frameDelta);hover[key]=value;CanvasInk.Box(g,r,Theme.Mix(primary?Color.FromArgb(77,30,37):Color.FromArgb(40,40,40),Color.FromArgb(109,56,63),value),10);CanvasInk.Text(g,text,new Rectangle(r.X+18,r.Y,r.Width-30,r.Height),17,Color.White,true);actions.Add(new RaceCanvasAction{Key=key,Bounds=r,Execute=a,Enabled=true});}
    protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Theme.Background);g.SmoothingMode=SmoothingMode.AntiAlias;scale=(float)Math.Min(Width/1050.0,Height/680.0);ox=(int)((Width-1050*scale)/2);oy=(int)((Height-680*scale)/2);var saved=g.Save();g.TranslateTransform(ox,oy);g.ScaleTransform(scale,scale);actions.Clear();double fade=Animated?Theme.Ease((Clock.Elapsed.TotalSeconds-lastDay)/.25):1;CanvasInk.Text(g,"КАЛЕНДАРЬ КОМАНДЫ / "+state.Year,new Rectangle(35,20,980,38),25,Color.White,true);CanvasInk.Text(g,CalendarFlow.Ready(state)?"Наступил день сессии":"До следующей сессии: "+Math.Max(0,CalendarFlow.RequiredDay(state)-state.Day)+" дн.",new Rectangle(36,63,980,28),16,Theme.Muted);CanvasInk.Box(g,new Rectangle(35,115,980,126),Theme.Card,16);CanvasInk.Text(g,"ДЕНЬ "+state.Day,new Rectangle(61,128,925,69),47,Color.FromArgb((int)(155+100*fade),Color.White),true);CanvasInk.Text(g,CalendarFlow.Ready(state)?Data.Tracks[state.Round].Country+" / "+Engine.Sessions(state)[state.Stage]:running?"Дни идут":"Пауза / можно вернуться к управлению командой",new Rectangle(63,201,920,26),17,Theme.Muted);
        for(int i=0;i<7;i++){int day=state.Day+i;var r=new Rectangle(35+i*142,263,128,118);var notes=CalendarFlow.Events(state,day);bool has=notes.Count>0;CanvasInk.Box(g,r,i==0?Color.FromArgb(68,31,37):Theme.Card,12);CanvasInk.Text(g,day.ToString("00"),new Rectangle(r.X+13,r.Y+9,100,39),29,Color.White,true);CanvasInk.Text(g,(has?notes[0]:i==0?"Сегодня / подготовка":"Подготовка"),new Rectangle(r.X+11,r.Y+53,108,57),11,has?Color.FromArgb(236,204,123):Theme.Muted,false,true);}
        CanvasInk.Text(g,"СОБЫТИЯ ДНЯ",new Rectangle(36,400,980,26),15,Theme.Muted,true);string[] shown=DayEvents.Length==0?new[]{"Команда готовится к следующему уикенду."}:DayEvents;for(int i=0;i<Math.Min(3,shown.Length);i++)CanvasInk.Text(g,"• "+shown[i],new Rectangle(40,438+i*43,970,40),18,Color.White,false,true);if(shown.Length>3)CanvasInk.Text(g,"Ещё "+(shown.Length-3)+" / подробности в радио паддока",new Rectangle(40,568,970,25),14,Theme.Muted);
        if(!CalendarFlow.Ready(state))Button(g,"calendar.toggle",running?"Пауза":"Продолжить дни",new Rectangle(35,607,265,46),Toggle,true);Button(g,"calendar.close",CalendarFlow.Ready(state)?"К следующей сессии":"Вернуться к команде",new Rectangle(660,607,355,46),Cancel,true);g.Restore(saved);}
    public override void Cancel(){if(Closing)return;save();if(Closed!=null)Closed();}
}
public partial class ManagerForm {
